const form=document.querySelector('#playgroundForm');const box=document.querySelector('#responseBox');form.addEventListener('submit',async(e)=>{e.preventDefault();box.textContent='Evaluating live policy…';try{const response=await fetch('/api/policies/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({actor:document.querySelector('#pgActor').value,counterparty:document.querySelector('#pgCounterparty').value,amount_usd:Number(document.querySelector('#pgAmount').value),intent:document.querySelector('#pgIntent').value,chain:'base'})});const data=await response.json();box.textContent=JSON.stringify(data,null,2)}catch(error){box.textContent=JSON.stringify({error:'REQUEST_FAILED',message:error.message},null,2)}});
